const webhookItem = $('LINE Webhook').first();
const replyToken = webhookItem ? webhookItem.json.body.events[0].replyToken : '';
const text = webhookItem ? webhookItem.json.body.events[0].message.text : '';
const isAddMode = text.includes('|加人') ? '|加人' : '';

const items = $input.all();
const staffSet = new Set();

items.forEach(item => {
  const row = item.json;
  for (const colName of Object.keys(row)) {
    if (colName === '日期' || colName === 'row_number') continue;
    const colStr = String(colName).trim();
    if (colStr.includes('男') || colStr.includes('女') || colStr.includes('號')) {
      const staffNum = colStr.replace('男', '').replace('女', '').replace('號', '').trim();
      if (staffNum) {
        staffSet.add(`${staffNum}號師傅`);
      }
    }
  }
});

const availableStaff = Array.from(staffSet).sort((a, b) => {
  const numA = parseInt(a.replace('號師傅', ''), 10) || 0;
  const numB = parseInt(b.replace('號師傅', ''), 10) || 0;
  return numA - numB;
});

const staffList = ['不指定', ...availableStaff];
const chunkSize = 5;
const bubbles = [];

for (let i = 0; i < staffList.length; i += chunkSize) {
  const chunkStaff = staffList.slice(i, i + chunkSize);
  const staffBoxes = [];

  chunkStaff.forEach(s => {
    const isUnspecified = (s === '不指定');
    const emoji = isUnspecified ? '⭐' : '👨‍⚕️';

    staffBoxes.push({
      "type": "box",
      "layout": "horizontal",
      "backgroundColor": "#f0f0f0",
      "cornerRadius": "sm",
      "paddingAll": "sm",
      "margin": "xs",
      "action": {
        "type": "message",
        "label": s,
        "text": `預約師傅:${s}|ts:${Date.now()}${isAddMode}`
      },
      "contents": [
        {
          "type": "text",
          "text": `${emoji} ${s}`,
          "size": "md",
          "align": "center",
          "color": "#333333",
          "weight": "bold"
        }
      ]
    });
  });

  const pageIndex = Math.floor(i / chunkSize) + 1;
  bubbles.push({
    "type": "bubble",
    "size": "micro",
    "header": {
      "type": "box",
      "layout": "vertical",
      "backgroundColor": "#1DB446",
      "paddingAll": "sm",
      "contents": [
        {
          "type": "text",
          "text": `步驟 1：選擇指定師傅 (${pageIndex})`,
          "weight": "bold",
          "size": "sm",
          "color": "#FFFFFF",
          "align": "center"
        }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "paddingAll": "sm",
      "contents": staffBoxes
    }
  });
}

return {
  json: {
    "replyToken": replyToken,
    "messages": [
      {
        "type": "flex",
        "altText": "請選擇預約師傅",
        "contents": {
          "type": "carousel",
          "contents": bubbles
        }
      }
    ]
  }
};

const webhookItem = $('LINE Webhook').first();
const text = webhookItem ? webhookItem.json.body.events[0].message.text : '';
const replyToken = webhookItem ? webhookItem.json.body.events[0].replyToken : '';

const isAddMode = text.includes('|加人') ? '|加人' : '';
const staffStr = text.replace('預約師傅:', '').replace(/\|ts:\d+/, '').replace('|加人', '').trim();

const items = $input.all();
const groups = {};
const categoryOrder = {};

items.forEach(item => {
  const row = item.json;
  const category = row['服務分類'] || row['服務項目'] || '其他';
  const serviceName = String(row['服務項目'] || '');
  const duration = row['時長 (分鐘)'] || row['時長(分鐘)'] || '';
  const priceRaw = String(row['價格'] || '');
  const orderRaw = row['排序'];

  if (!serviceName) return;

  const numericPrice = parseInt(priceRaw.replace(/[^\d]/g, ''), 10) || 0;
  const categorySortNum = (orderRaw !== undefined && orderRaw !== '' && !isNaN(orderRaw)) ? Number(orderRaw) : 999;
  if (categoryOrder[category] === undefined || categorySortNum < categoryOrder[category]) {
    categoryOrder[category] = categorySortNum;
  }

  const lines = serviceName.split('\n').map(s => s.trim()).filter(Boolean);
  const isMultiLine = lines.length > 1;
  const isPerCount = priceRaw.includes('/次');

  let line1 = lines[0] || '';
  let line2 = '';

  if (isMultiLine) {
    line2 = lines[1] || '';
  } else if (!isPerCount) {
    line2 = `(${duration}分鐘)`;
  }

  const buttonLabel = priceRaw.startsWith('$') ? `預約 ${priceRaw}` : `預約 $${priceRaw}`;
  const cleanServiceName = serviceName.replace(/\n/g, ' ');

  if (!groups[category]) groups[category] = [];
  groups[category].push({
    line1: line1,
    line2: line2,
    duration: duration,
    numericPrice: numericPrice,
    buttonLabel: buttonLabel,
    actionText: `預約項目:${staffStr}|${cleanServiceName}|${duration}|ts:${Date.now()}${isAddMode}`
  });
});

const sortedCategories = Object.keys(groups).sort((a, b) => categoryOrder[a] - categoryOrder[b]);

const bubbles = sortedCategories.map(category => {
  groups[category].sort((a, b) => a.numericPrice - b.numericPrice);

  const serviceBlocks = [];
  groups[category].forEach((svc, index) => {
    if (index > 0) {
      serviceBlocks.push({
        "type": "separator",
        "margin": "sm"
      });
    }

    const textContents = [
      {
        "type": "text",
        "text": svc.line1,
        "size": "sm",
        "color": "#333333",
        "weight": "bold",
        "align": "center",
        "wrap": true
      }
    ];

    if (svc.line2) {
      textContents.push({
        "type": "text",
        "text": svc.line2,
        "size": "sm",
        "color": svc.line2.startsWith('(') ? "#666666" : "#333333",
        "weight": "bold",
        "align": "center",
        "wrap": true
      });
    }

    serviceBlocks.push({
      "type": "box",
      "layout": "vertical",
      "margin": "sm",
      "spacing": "xs",
      "contents": [
        ...textContents,
        {
          "type": "button",
          "style": "secondary",
          "height": "sm",
          "margin": "xs",
          "action": {
            "type": "message",
            "label": svc.buttonLabel,
            "text": svc.actionText
          }
        }
      ]
    });
  });

  return {
    "type": "bubble",
    "size": "micro",
    "header": {
      "type": "box",
      "layout": "vertical",
      "backgroundColor": "#1DB446",
      "paddingAll": "sm",
      "contents": [
        {
          "type": "text",
          "text": category,
          "weight": "bold",
          "size": "md",
          "color": "#FFFFFF",
          "align": "center"
        }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "paddingAll": "sm",
      "contents": serviceBlocks
    }
  };
});

return {
  json: {
    "replyToken": replyToken,
    "messages": [
      {
        "type": "flex",
        "altText": "請選擇預約項目",
        "contents": {
          "type": "carousel",
          "contents": bubbles
        }
      }
    ]
  }
};

const webhookItem = $('LINE Webhook').first();
const replyToken = webhookItem ? webhookItem.json.body.events[0].replyToken : '';
const text = webhookItem ? webhookItem.json.body.events[0].message.text : '';

const isAddMode = text.includes('|加人') ? '|加人' : '';
const parts = text.replace('預約項目:', '').replace('|加人', '').split('|');
const staffStr = parts[0] ? parts[0].trim() : '不指定';
const serviceName = parts[1] || '按摩';
const duration = parts[2] || '60';

// 提取師傅號碼 (如 "1號師傅" -> "1")
const staffNumMatch = staffStr.match(/\d+/);
const targetStaffNum = staffNumMatch ? staffNumMatch[0] : '';

// 讀取班表與預約資料 (請確保前置節點名稱與工作流一致)
let scheduleRows = [];
let existingAppointments = [];

try {
  scheduleRows = $('讀取班表 Staff_Schedule1').all().map(i => i.json);
} catch (e) {
  scheduleRows = [];
}

try {
  existingAppointments = $('讀取預約 Bookings3').all().map(i => i.json);
} catch (e) {
  existingAppointments = [];
}

// 輔助函式：時間轉分鐘數
const parseTimeToMinutes = (tStr) => {
  if (!tStr) return 0;
  const cleanT = String(tStr).replace(' (次日)', '').trim();
  const [h, m] = cleanT.split(':').map(Number);
  let totalM = (h || 0) * 60 + (m || 0);
  if (String(tStr).includes('次日') || (h || 0) < 6) totalM += 24 * 60;
  return totalM;
};

// 店家營業開放時間清單 (可依實際經營時段調整)
const rawTimes = [];
for (let hour = 11; hour <= 23; hour++) {
  rawTimes.push(`${String(hour).padStart(2, '0')}:00`);
  rawTimes.push(`${String(hour).padStart(2, '0')}:30`);
}
rawTimes.push('00:00', '00:30', '01:00');

// 比對每日排班與剩餘空檔
const scheduleMap = {};

scheduleRows.forEach(row => {
  const dateKey = String(row['日期'] || '').trim().substring(0, 10);
  if (!dateKey) return;

  let workTimeStr = '';
  for (const [colName, val] of Object.entries(row)) {
    if (colName === '日期' || colName === 'row_number') continue;
    const cleanCol = colName.replace('男', '').replace('女', '').replace('號', '').trim();
    if (staffStr === '不指定' || cleanCol === targetStaffNum) {
      if (val && String(val).trim() !== '') {
        workTimeStr = String(val).trim();
        break;
      }
    }
  }

  // 無班表或格式不符算作休假 (OFF)
  if (!workTimeStr || !workTimeStr.includes('-')) {
    scheduleMap[dateKey] = 'OFF';
    return;
  }

  // 解析上班時間區間
  const [startPart, endPart] = workTimeStr.split('-').map(s => s.trim());
  const parseWorkTime = (p) => {
    if (p.includes(':')) {
      const [h, m] = p.split(':').map(Number);
      return h * 60 + (m || 0);
    } else {
      const h = Math.floor(parseInt(p, 10) / 100);
      const m = parseInt(p, 10) % 100;
      return h * 60 + m;
    }
  };

  const workStartM = parseWorkTime(startPart);
  let workEndM = parseWorkTime(endPart);
  if (workEndM <= workStartM) workEndM += 24 * 60;

  // 檢查當日是否至少有一個未被預約的空檔
  const hasAvailableSlot = rawTimes.some(timeStr => {
    const targetStartM = parseTimeToMinutes(timeStr);
    const targetEndM = targetStartM + 60;

    if (targetStartM < workStartM || targetEndM > workEndM) return false;

    let isConflict = false;
    existingAppointments.forEach(appt => {
      const apptDate = String(appt['預約日期'] || '').trim().substring(0, 10);
      const apptStaff = String(appt['指定師傅'] || appt['師傅姓名'] || '').trim();
      const apptStatus = String(appt['Status'] || appt['狀態'] || '').trim();

      if (apptDate === dateKey && apptStatus !== '已取消') {
        if (staffStr === '不指定' || apptStaff.includes(targetStaffNum)) {
          const apptStartStr = String(appt['開始時間'] || '').trim();
          const apptEndStr = String(appt['結束時間'] || '').trim();
          if (apptStartStr && apptEndStr) {
            const apptStartM = parseTimeToMinutes(apptStartStr);
            const apptEndM = parseTimeToMinutes(apptEndStr);
            if (Math.max(targetStartM, apptStartM) < Math.min(targetEndM, apptEndM)) {
              isConflict = true;
            }
          }
        }
      }
    });

    return !isConflict;
  });

  scheduleMap[dateKey] = hasAvailableSlot ? 'AVAILABLE' : 'FULL';
});

// 時區計算：台灣標準時間 UTC+8
const now = new Date();
const twNow = new Date(now.getTime() + (8 * 60 * 60 * 1000) + (now.getTimezoneOffset() * 60 * 1000));
const currentDay = twNow.getUTCDate();
let totalDays = currentDay >= 25 ? 28 : new Date(twNow.getUTCFullYear(), twNow.getUTCMonth() + 1, 0).getDate() - currentDay + 1;

const totalWeeks = Math.ceil(totalDays / 7);
const oneDayTime = 24 * 60 * 60 * 1000;

const getTaiwanDateStr = (offsetDays = 0) => {
  const d = new Date(twNow.getTime() + (offsetDays * oneDayTime));
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`;
};

const weekdays = ['日', '一', '二', '三', '四', '五', '六'];
const bubbles = [];

for (let week = 0; week < totalWeeks; week++) {
  const dateBoxes = [];

  for (let i = 0; i < 7; i++) {
    const dayIndex = week * 7 + i;
    if (dayIndex >= totalDays) break;

    const dateStr = getTaiwanDateStr(dayIndex);
    const targetDate = new Date(twNow.getTime() + (dayIndex * oneDayTime));
    const dayOfWeek = targetDate.getUTCDay(); 
    const isWeekend = (dayOfWeek === 0 || dayOfWeek === 6);
    const monthDay = `${targetDate.getUTCMonth() + 1}/${targetDate.getUTCDate()}`;
    const weekStr = `(週${weekdays[dayOfWeek]})`;

    const status = scheduleMap[dateStr] || 'OFF';

    if (status === 'AVAILABLE') {
      dateBoxes.push({
        "type": "box",
        "layout": "horizontal",
        "backgroundColor": "#f0f0f0",
        "cornerRadius": "sm",
        "paddingAll": "sm",
        "margin": "xs",
        "action": {
          "type": "message",
          "label": `${monthDay} ${weekStr}`,
          "text": `預約日期:${staffStr}|${serviceName}|${duration}|${dateStr}|ts:${Date.now()}${isAddMode}`
        },
        "contents": [
          {
            "type": "text",
            "text": `${monthDay} ${weekStr}`,
            "size": "md",
            "align": "center",
            "color": isWeekend ? '#FF4b4b' : '#333333',
            "weight": isWeekend ? "bold" : "regular"
          }
        ]
      });
    } else {
      const tagText = status === 'FULL' ? '(滿)' : '(休)';
      dateBoxes.push({
        "type": "box",
        "layout": "horizontal",
        "backgroundColor": "#E0E0E0",
        "cornerRadius": "sm",
        "paddingAll": "sm",
        "margin": "xs",
        "contents": [
          {
            "type": "text",
            "text": `${monthDay} ${weekStr} ${tagText}`,
            "size": "md",
            "align": "center",
            "color": "#999999",
            "weight": "regular"
          }
        ]
      });
    }
  }

  const startDateStr = getTaiwanDateStr(week * 7);
  const actualEndIndex = Math.min((week * 7 + 6), totalDays - 1);
  const endDateStr = getTaiwanDateStr(actualEndIndex);
  const subTitle = `(${startDateStr.slice(5)} ~ ${endDateStr.slice(5)})`;
  const mainTitle = week === 0 ? '本週可預約日期' : `第 ${week + 1} 週`;

  bubbles.push({
    "type": "bubble",
    "size": "micro",
    "header": {
      "type": "box",
      "layout": "vertical",
      "backgroundColor": "#1DB446",
      "paddingAll": "sm",
      "contents": [
        {
          "type": "text",
          "text": mainTitle,
          "weight": "bold",
          "size": "sm",
          "color": "#FFFFFF",
          "align": "center"
        },
        {
          "type": "text",
          "text": subTitle,
          "size": "xs",
          "color": "#FFFFFFCC",
          "align": "center",
          "margin": "xs"
        }
      ]
    },
    "body": {
      "type": "box",
      "layout": "vertical",
      "paddingAll": "sm",
      "contents": dateBoxes
    }
  });
}

return {
  json: {
    "replyToken": replyToken,
    "messages": [
      {
        "type": "flex",
        "altText": "請選擇預約日期",
        "contents": {
          "type": "carousel",
          "contents": bubbles
        }
      }
    ]
  }
};

const webhookItem = $('LINE Webhook').first();
const text = webhookItem ? webhookItem.json.body.events[0].message.text : '';
const replyToken = webhookItem ? webhookItem.json.body.events[0].replyToken : '';
const isAddMode = text.includes('|加人') ? '|加人' : '';

let cleanText = text.replace('預約日期:', '').replace('|加人', '');
const parts = cleanText.split('|');

const staffStr = parts[0] ? parts[0].trim() : '不指定';
const serviceName = parts[1] || '按摩';
const duration = parseInt(parts[2] || '60', 10);
const dateStr = parts[3] ? parts[3].trim() : '';

let scheduleRows = [];
let existingAppointments = [];

try {
  scheduleRows = $('讀取班表 Staff_Schedule').all().map(i => i.json);
} catch (e) {
  scheduleRows = [];
}

try {
  existingAppointments = $('讀取預約 Bookings').all().map(i => i.json);
} catch (e) {
  existingAppointments = [];
}

const now = new Date();
const twNow = new Date(now.getTime() + (8 * 60 * 60 * 1000) + (now.getTimezoneOffset() * 60 * 1000));
const todayStr = `${twNow.getUTCFullYear()}-${String(twNow.getUTCMonth() + 1).padStart(2, '0')}-${String(twNow.getUTCDate()).padStart(2, '0')}`;
const currentHour = twNow.getUTCHours();
const currentMinute = twNow.getUTCMinutes();

const parseTimeToMinutes = (tStr) => {
  if (!tStr) return 0;
  const cleanT = String(tStr).replace(' (次日)', '').trim();
  const [h, m] = cleanT.split(':').map(Number);
  let totalM = (h || 0) * 60 + (m || 0);
  if (String(tStr).includes('次日') || (h || 0) < 6) {
    totalM += 24 * 60;
  }
  return totalM;
};

const rawTimes = [];
for (let hour = 11; hour <= 23; hour++) {
  rawTimes.push(`${String(hour).padStart(2, '0')}:00`);
  rawTimes.push(`${String(hour).padStart(2, '0')}:30`);
}
rawTimes.push('00:00');
rawTimes.push('00:30');
rawTimes.push('01:00');

const availableTimes = rawTimes.filter(timeStr => {
  if (dateStr === todayStr) {
    const [tHour, tMinute] = timeStr.split(':').map(Number);
    if (tHour >= 0 && tHour <= 3) return false;
    if (tHour < currentHour || (tHour === currentHour && tMinute <= currentMinute)) return false;
  }

  const targetStartM = parseTimeToMinutes(timeStr);
  const targetEndM = targetStartM + duration;

  const targetRow = scheduleRows.find(row => String(row['日期'] || '').trim().substring(0, 10) === dateStr);
  if (!targetRow) return false;

  let activeStaffList = [];
  for (const [colName, workTime] of Object.entries(targetRow)) {
    if (colName === '日期' || colName === 'row_number') continue;
    if (!workTime || String(workTime).trim() === '') continue;

    const workStr = String(workTime).trim();
    if (workStr.includes('-')) {
      const [startPart, endPart] = workStr.split('-').map(s => s.trim());
      const parseWorkTime = (p) => {
        if (p.includes(':')) {
          const [h, m] = p.split(':').map(Number);
          return h * 60 + (m || 0);
        } else {
          const h = Math.floor(parseInt(p, 10) / 100);
          const m = parseInt(p, 10) % 100;
          return h * 60 + m;
        }
      };

      const workStartM = parseWorkTime(startPart);
      let workEndM = parseWorkTime(endPart);
      if (workEndM <= workStartM) workEndM += 24 * 60;

      if (targetStartM >= workStartM && targetEndM <= workEndM) {
        const colStr = String(colName).trim();
        let staffNum = colStr.replace('男', '').replace('女', '').replace('號', '').trim();
        let staffName = `${staffNum}號師傅`;

        if (staffStr !== '不指定' && staffStr !== staffName) continue;

        let isConflict = false;
        existingAppointments.forEach(appt => {
          const apptDate = String(appt['預約日期'] || '').trim().substring(0, 10);
          const apptStaff = String(appt['指定師傅'] || appt['師傅姓名'] || '').trim();
          const apptStatus = String(appt['Status'] || appt['狀態'] || '').trim();

          if (apptDate === dateStr && apptStaff.includes(staffNum) && apptStatus !== '已取消') {
            const apptStartStr = String(appt['開始時間'] || '').trim();
            const apptEndStr = String(appt['結束時間'] || '').trim();
            if (apptStartStr && apptEndStr) {
              const apptStartM = parseTimeToMinutes(apptStartStr);
              const apptEndM = parseTimeToMinutes(apptEndStr);
              if (Math.max(targetStartM, apptStartM) < Math.min(targetEndM, apptEndM)) {
                isConflict = true;
              }
            }
          }
        });

        if (!isConflict) {
          activeStaffList.push(staffName);
        }
      }
    }
  }

  return activeStaffList.length > 0;
});

if (availableTimes.length === 0) {
  return {
    json: {
      replyToken: replyToken,
      messages: [
        {
          "type": "text",
          "text": `⚠️ 此日期（${dateStr}）該師傅無可預約的空閒時段，請更換日期或選取其他師傅！`
        }
      ]
    }
  };
}

// 修正重點：設定每頁固定幾筆（例如一頁 5 個按鈕），並動態計算實際需要的頁數
const itemsPerPage = 5;
const totalPages = Math.ceil(availableTimes.length / itemsPerPage);
const bubbles = [];

for (let page = 0; page < totalPages; page++) {
  const chunkTimes = availableTimes.slice(page * itemsPerPage, (page + 1) * itemsPerPage);
  const timeBoxes = [];

  chunkTimes.forEach(t => {
    const isNextDay = t === '00:00' || t === '00:30' || t === '01:00';
    const labelDisplay = isNextDay ? `⏰ ${t} (次日)` : `⏰ ${t}`;

    timeBoxes.push({
      "type": "box",
      "layout": "horizontal",
      "backgroundColor": "#f0f0f0",
      "cornerRadius": "sm",
      "paddingAll": "sm",
      "margin": "xs",
      "action": {
        "type": "message",
        "label": `${t}${isNextDay ? ' (次日)' : ''}`,
        "text": `預約時間:${dateStr}|${t}|${serviceName}|${duration}|${staffStr}|ts:${Date.now()}${isAddMode}`
      },
      "contents": [
        {
          "type": "text",
          "text": labelDisplay,
          "size": "md",
          "align": "center",
          "color": isNextDay ? "#d9534f" : "#333333",
          "weight": "bold"
        }
      ]
    });
  });

  bubbles.push({
    "type": "bubble",
    "size": "micro",
    "header": {
      "type": "box",
      "layout": "vertical",
      "backgroundColor": "#1DB446",
      "paddingAll": "sm",
      "contents": [
        {
          "type": "text",
