const webhookItem = $('LINE Webhook').first();
const currentUserId = webhookItem ? webhookItem.json.body.events[0]?.source?.userId : '';
const replyToken = webhookItem ? webhookItem.json.body.events[0]?.replyToken : '';
const text = webhookItem ? webhookItem.json.body.events[0]?.message?.text : '';

// 解析預約請求字串
const parts = text.replace('預約時間:', '').split('|');
const dateStr = parts[0] || '';
const timeStr = parts[1] || '';
const serviceStr = parts[2] || '';
const duration = parseInt(parts[3] || '60', 10);
const staffStr = parts[4] || '不指定';

let endTimeStr = '';
if (timeStr) {
  const [h, m] = timeStr.split(':').map(Number);
  const totalM = h * 60 + m + duration;
  const endH = Math.floor(totalM / 60) % 24;
  const endM = totalM % 60;
  endTimeStr = `${String(endH).padStart(2, '0')}:${String(endM).padStart(2, '0')}`;
}

// 讀取「讀取預約是否成功」節點傳過來的試算表資料
const items = $input.all().map(i => i.json);

// 精準過濾出：與本次請求的「預約日期、開始時間、指定師傅」完全一致，且「狀態不等於已取消」的紀錄
const matchedBookings = items.filter(b => {
  const bDate = String(b['預約日期'] || '').trim().substring(0, 10);
  const bTime = String(b['開始時間'] || '').trim();
  const bStaff = String(b['指定師傅'] || '').trim();
  const bStatus = String(b['狀態'] || b['Status'] || '').trim();

  return bDate === dateStr && bTime === timeStr && bStaff === staffStr && bStatus !== '已取消';
});

// 將符合條件的紀錄按 row_number 嚴格升冪排序（最先寫入試算表的人排第一個）
matchedBookings.sort((a, b) => (Number(a.row_number) || 0) - (Number(b.row_number) || 0));

// 取得最先寫入試算表的勝出者
const winner = matchedBookings[0] || null;

// 只有最先寫入（row_number 最小）且 顧客姓名 等於當前使用者，才是唯一成功者！
const isSuccess = winner && (String(winner['顧客姓名']).trim() === String(currentUserId).trim());

const footerButtons = [
  {
    "type": "button",
    "style": "primary",
    "color": "#1DB446",
    "height": "sm",
    "action": {
      "type": "message",
      "label": "🔍 查詢預約",
      "text": "查詢預約"
    }
  }
];

let flexMessageContent;

if (isSuccess) {
  flexMessageContent = {
    "type": "bubble",
    "body": {
      "type": "box",
      "layout": "vertical",
      "contents": [
