const isAddMode = text.includes('|加人');

let buttonValidMinutes = 30;
try {
  buttonValidMinutes = $('按鈕有效期設定').first().json.buttonValidMinutes;
} catch (e) {}

// ① 按鈕時效判斷：從文字中撈出 ts:數字
const tsMatch = text.match(/\|ts:(\d+)/);
let isExpired = true; // 找不到時間戳記，一律視為逾期
if (tsMatch) {
  const issuedAt = parseInt(tsMatch[1], 10);
  const elapsedMinutes = (Date.now() - issuedAt) / 60000;
  isExpired = elapsedMinutes > buttonValidMinutes;
}

if (isExpired) {
  return { json: { status: 'EXPIRED', replyToken } };
}

// ② 重複預約判斷（若是「動作:增加|加人」的加人流程，代表使用者已經確認要新增，跳過此檢查）
if (!isAddMode) {
  const now = new Date();
  const twNow = new Date(now.getTime() + (8 * 60 * 60 * 1000) + (now.getTimezoneOffset() * 60 * 1000));
  const todayStr = `${twNow.getUTCFullYear()}-${String(twNow.getUTCMonth() + 1).padStart(2, '0')}-${String(twNow.getUTCDate()).padStart(2, '0')}`;
  const limitDate = new Date(twNow.getTime() + 7 * 24 * 60 * 60 * 1000);
  const limitDateStr = `${limitDate.getUTCFullYear()}-${String(limitDate.getUTCMonth() + 1).padStart(2, '0')}-${String(limitDate.getUTCDate()).padStart(2, '0')}`;

  const items = $input.all().map(i => i.json);
  const userBookings = items.filter(appt => {
    const status = String(appt['狀態'] || appt['Status'] || '已預約').trim();
    const apptDate = String(appt['預約日期'] || '').trim().substring(0, 10);
    return status !== '已取消' && apptDate >= todayStr && apptDate <= limitDateStr;
  });

  if (userBookings.length > 0) {
    return {
      json: {
        status: 'DUPLICATE',
        replyToken: replyToken,
        hasBooking: true,
        bookingCount: userBookings.length,
        userBookings: userBookings
      }
    };
  }
}

return { json: { status: 'OK' } };

const now = new Date();

// 篩選出已經結束且狀態還是「已預約」的資料
const expiredRows = $input.all().filter(item => {
  const row = item.json;
  if (row['狀態'] !== '已預約') return false;

  // 組合預約結束日期與時間 (例如 "2026-08-09 13:20")
  const endDateTime = new Date(`${row['預約日期']} ${row['結束時間']}`);

  return endDateTime < now;
});

// 將需要更新的列回傳，並將狀態改為「已完成」
return expiredRows.map(item => {
  return {
    json: {
      row_number: item.json.row_number, // 用於 Google Sheets 定位更新
      狀態: '已完成'
    }
  };
});
